/* Types */
/**  A coding-agent CLI that Muster recognises inside a session's process tree. */
export type AgentKind = "opencode" | "claude_code" | "codex" | "kimi_code" | "aider" | "gemini" | "goose" | "atomcode";

/**
 *  Three-state model: `Working` (alive, output recently), `Waiting` (alive,
 *  silent — likely needs input), or `Done` (agent exited, session alive, the
 *  user hasn't viewed the tab yet; the dot drops once they do).
 */
export type AgentState = "working" | "waiting" | "done";

export type AgentStatusChanged = {
	sessions: AgentStatusRow[],
};

export type AgentStatusRow = {
	id: string,
	agent: AgentKind | null,
	state: AgentState | null,
	title: string | null,
	project: string | null,
};

export type AllAgentStatus = {
	sessions: AgentStatusRow[],
};

/**  Frontend-facing serialized projection of the live state. */
export type AppStateView = {
	projects: ProjectView[],
	selected_project_id: string | null,
	is_left_sidebar_visible: boolean,
	is_panel_visible: boolean,
	panel_tab: RightPanel,
	has_split_panes: boolean,
	is_pane_zoomed: boolean,
};

export type AppTheme = "system" | "light" | "dark";

/**  One line of a file annotated with the commit that last touched it. */
export type BlameLine = {
	/**  1-based line number in the current file. */
	line: number,
	short_hash: string,
	author: string,
	/**  Relative age (reuses `relative_date`; no chrono dependency). */
	date: string,
};

export type DiffTabInfo = {
	id: string,
	repo_root: string,
	path: string,
	staged: boolean,
	/**  Non-null when this diff compares two commits. */
	old_rev: string | null,
	new_rev: string | null,
	old: string,
	new: string,
	error: string | null,
	loading: boolean,
};

/**  One entry of a directory listing for the file tree. */
export type DirEntry = {
	name: string,
	path: string,
	is_directory: boolean,
};

/**  One unsaved file entry shown in the close-confirmation dialog. */
export type DirtyFileInfo = {
	id: string,
	name: string,
};

/**  One commit that touched a path, as reported by `git log --follow`. */
export type FileCommit = {
	hash: string,
	short_hash: string,
	/**  First parent hash (empty for a root commit), used for "diff vs parent". */
	parent: string | null,
	subject: string,
	author: string,
	relative_date: string,
	/**  epoch ms */
	date_ms: number,
};

export type FileReveal = {
	id: string,
	line: number,
};

export type FileSaved = {
	id: string,
};

export type FileTabInfo = {
	id: string,
	path: string,
	name: string,
	content_kind: string,
	text: string,
	is_dirty: boolean,
};

export type FocusDirection = "up" | "down" | "left" | "right" | "next" | "previous";

export type FsChanged = {
	dir: string,
};

/**
 *  Fingerprint of the repo + target files, re-validated before a discard
 *  runs. Any drift aborts the operation.
 */
export type GitGuard = {
	head_oid: string | null,
	branch: string | null,
	entries: GuardEntry[],
};

export type GitStatusEntry = {
	path: string,
	staged: string,
	unstaged: string,
	is_untracked: boolean,
	is_conflict: boolean,
	orig_path: string | null,
	/**
	 *  Per-file line counts for the row badge. Semantics follow the section:
	 *  staged rows count HEAD→index, changed rows count index→workdir
	 *  (untracked rows count the file's lines as additions). 0/0 for binary
	 *  files, conflicts, and anything that couldn't be counted.
	 */
	additions: number,
	deletions: number,
};

export type GitStatusInfo = {
	is_repo: boolean,
	repo_root: string,
	root_path: string,
	branch: string | null,
	upstream: string | null,
	ahead: number,
	behind: number,
	has_upstream: boolean,
	merge_entries: GitStatusEntry[],
	staged_entries: GitStatusEntry[],
	changed_entries: GitStatusEntry[],
	branches: string[],
	remotes: string[],
	recent_commits: RecentCommit[],
	stash_count: number,
	/**
	 *  Insertions/deletions of the HEAD → workdir+index diff, with untracked
	 *  text files counted as additions (git's numstat omits them).
	 */
	line_additions: number,
	line_deletions: number,
	error: string | null,
	/**  True when this repository is a linked worktree (not the main checkout). */
	is_worktree: boolean,
	/**
	 *  Cheap fingerprint of the index/HEAD at compute time. The frontend
	 *  polls the lightweight `status_revision` before requesting a full
	 *  snapshot, so an idle repo never re-transfers a multi-MB payload.
	 */
	revision: string,
};

/**
 *  Per-file snapshot taken when a destructive confirmation opens: enough to
 *  detect that the file was written to (or deleted) while the dialog was up.
 */
export type GuardEntry = {
	path: string,
	exists: boolean,
	size: number,
	mtime_ms: number,
};

/**
 *  One row of the PORTS section: a listening TCP port owned by one of the
 *  session's processes or by a process working in the project directory.
 */
export type ListenPort = {
	port: number,
	pid: number,
	process_name: string,
};

export type NotificationActivate = {
	id: string,
};

export type OpenSettings = null;

/**
 *  One tile in a tab's layout. A value type so structural changes reassign the
 *  enclosing column array and the frontend re-renders.
 */
export type Pane = {
	id: string,
	content: PaneContent,
	/**  Relative vertical share within its column. */
	weight: number,
};

/**  A vertical stack of panes; columns tile left-to-right across the tab. */
export type PaneColumn = {
	id: string,
	panes: Pane[],
	/**  Relative horizontal share within the tab. */
	weight: number,
};

/**
 *  The leaf content of a pane: a terminal session, an open file, or a git diff.
 * 
 *  Each variant carries the *id* of the managed resource so the frontend can
 *  look up its own rendered state without the backend needing to ship the
 *  full payload over the FFI boundary on every render.
 */
export type PaneContent = { kind: "session"; id: string } | { kind: "file"; id: string } | { kind: "diff"; id: string };

/**  Which side of a target pane a dragged pane is dropped on. */
export type PaneDropEdge = "left" | "right" | "top" | "bottom";

/**  One row of the PROCESSES section. */
export type ProcessInfo = {
	pid: number,
	name: string,
	cpu: number,
	mem_bytes: number,
	exe: string,
};

export type ProjectView = {
	id: string,
	name: string,
	custom_name: string | null,
	custom_directory: string | null,
	tabs: TabView[],
	selected_tab_id: string | null,
	session_count: number,
};

export type PtyData = {
	id: string,
	data: string,
};

export type PtyExit = {
	id: string,
};

export type PtyProgress = {
	id: string,
	state: number,
	progress: number,
};

export type RecentCommit = {
	hash: string,
	short_hash: string,
	subject: string,
	author: string,
	relative_date: string,
};

export type ResizeDirection = "up" | "down" | "left" | "right";

export type RightPanel = "files" | "git" | "info";

/**  One matching line in one file (offsets are char-based into `line_text`). */
export type SearchMatch = {
	path: string,
	rel_path: string,
	line: number,
	column: number,
	line_text: string,
	match_start: number,
	match_len: number,
};

/**
 *  One row of the `agent_status_snapshot` command: the live detection for a
 *  session, plus its display title so UI lists (close confirmation, command
 *  palette) don't need a second round-trip.
 */
export type SessionAgentStatus = {
	session_id: string,
	agent: AgentKind,
	state: AgentState,
	title: string,
};

export type SessionCwdChanged = {
	id: string,
	cwd: string,
};

export type SessionInfo = {
	id: string,
	project_id: string,
	title: string,
	working_directory: string,
	shell_name: string,
	has_exited: boolean,
	pid: number | null,
};

export type Settings = {
	theme?: AppTheme,
	theme_dark?: string,
	theme_light?: string,
	font_family?: string,
	font_size?: number,
	ui_font_size?: number,
	font_thicken?: boolean,
	editor_wrap_lines?: boolean,
	/**  Diff viewer layout: side-by-side (true) or unified/inline (false). */
	diff_side_by_side?: boolean,
	/**
	 *  Info panel PORTS: also include listeners from processes that merely
	 *  work inside the project directory (dev servers started outside the
	 *  session), not just the session's own process tree.
	 */
	project_ports?: boolean,
	/**
	 *  Terminal right-click behavior: "menu" opens the context menu, "smart"
	 *  copies the selection (or pastes when nothing is selected) Windows
	 *  Terminal style. Shift+right-click always opens the menu.
	 */
	terminal_right_click?: string,
	/**
	 *  Default shell for new sessions: "auto" (detect pwsh → powershell →
	 *  wsl → cmd) or a specific shell id from `shell::available_shells`.
	 *  Falls back to auto when the named shell is not installed.
	 */
	default_shell?: string,
	language?: string,
};

export type SettingsChanged = null;

/**
 *  One entry of the Settings dialog's default-shell picker: a stable id
 *  (stored in `Settings::default_shell`), a display name, and whether the
 *  shell is actually installed on this machine.
 */
export type ShellOption = {
	id: string,
	name: string,
	path: string,
	available: boolean,
};

export type StateChanged = AppStateView;

export type TabFocused = string;

export type TabView = {
	id: string,
	custom_name: string | null,
	display_title: string | null,
	columns: PaneColumn[],
	focused_pane_id: string,
	is_zoomed: boolean,
	pane_count: number,
};

/**  Resolved color palette for window chrome and terminal alike. */
export type ThemeColors = {
	name: string,
	background: string,
	foreground: string,
	cursor: string,
	accent: string,
	selection_bg: string,
	selection_fg: string,
	sidebar: string,
	divider: string,
	palette: [string, string, string, string, string, string, string, string, string, string, string, string, string, string, string, string],
};

/**
 *  Lightweight theme metadata for the settings picker: name, dark/light
 *  classification, and two swatch colors for a visual preview.
 */
export type ThemeInfo = {
	name: string,
	is_dark: boolean,
	background: string,
	accent: string,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

